import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { PrismaClient, Deck, Card, QuizAttempt } from '@prisma/client';

export interface CreateDeckInput {
  title: string;
  description?: string;
  cards: { front: string; back: string }[];
}

export class PrismaDeckRepository {
  constructor(private prisma: PrismaClient) {}

  async getDecksWithStats(): Promise<(Deck & { _count: { cards: number }; recentScore?: number })[]> {
    const decks = await this.prisma.deck.findMany({
      include: {
        _count: {
          select: { cards: true },
        },
        attempts: {
          orderBy: { createdAt: 'desc' },
          take: 1,
        },
      },
      orderBy: { updatedAt: 'desc' },
    });

    return decks.map(({ attempts, ...deck }) => ({
      ...deck,
      recentScore: attempts[0]?.score,
    }));
  }

  async createDeck(data: CreateDeckInput): Promise<Deck> {
    return this.prisma.deck.create({
      data: {
        title: data.title,
        description: data.description,
        cards: {
          create: data.cards,
        },
      },
      include: { cards: true },
    });
  }

  async recordQuizAttempt(deckId: string, score: number, total: number): Promise<QuizAttempt> {
    return this.prisma.quizAttempt.create({
      data: {
        deckId,
        score,
        total,
      },
    });
  }
}

import { useState, useCallback } from 'react';

export interface CardItem {
  id: string;
  front: string;
  back: string;
}

export function useFlashcardQuiz(cards: CardItem[]) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [correctCount, setCorrectCount] = useState(0);
  const [isFinished, setIsFinished] = useState(false);

  const currentCard = cards[currentIndex];

  const handleFlip = useCallback(() => {
    setIsFlipped((prev) => !prev);
  }, []);

  const handleAnswer = useCallback((remembered: boolean) => {
    if (remembered) {
      setCorrectCount((prev) => prev + 1);
    }
    setIsFlipped(false);
    if (currentIndex + 1 < cards.length) {
      setCurrentIndex((prev) => prev + 1);
    } else {
      setIsFinished(true);
    }
  }, [currentIndex, cards.length]);

  const resetQuiz = useCallback(() => {
    setCurrentIndex(0);
    setIsFlipped(false);
    setCorrectCount(0);
    setIsFinished(false);
  }, []);

  return {
    currentCard,
    currentIndex,
    totalCards: cards.length,
    isFlipped,
    isFinished,
    correctCount,
    handleFlip,
    handleAnswer,
    resetQuiz,
  };
}
